function open(type,data={}){if(!modal)lastFocus=document.activeElement;modal={type,...data};S.formError='';renderModal();later(()=>$('#overlay input, #overlay textarea, #overlay button')?.focus(),0)}
function close(update=true){detailBeforeClose();if(modal?.type==='voice'){S.voice='idle'}modal=null;$('#overlay').hidden=true;$('#overlay').innerHTML='';if(update){render();lastFocus?.isConnected&&lastFocus.focus()}}
function sheet(title,body,footer=''){return `<section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><div class="sheet-head"><h2>${title}</h2>${btn('','close','','close')}</div>${body}${S.formError?`<p class="danger" role="alert">${esc(S.formError)}</p>`:''}${footer?`<div class="sheet-foot">${footer}</div>`:''}</section>`}
function confirm(title,body,action){open('confirm',{title,body,confirmAction:action})}
