function modelOptions(){const arr=['Helix 内置 · 演示模型','自配 API · 示例模型','订阅服务 · 示例模型','本地模型 · 示例模型'];return arr.filter(x=>x.toLowerCase().includes(S.modelQuery.toLowerCase())).map(x=>btn((S.modelCandidate===x?'✓ ':'')+esc(x)+(x.startsWith('Helix')&&S.account!=='member'?' · 需登录':''),'model-candidate:'+x,'listrow','model')).join('')||empty('没有匹配模型')}
