function send(){if(S.stream)return;const d=S.draft.trim();if(!d&&!S.attachments.length&&!S.references.length){toast('先输入消息或添加材料');return}const command=d.match(/^\/(chat|plan|act|goal)(?:\s|$)/i);if(command){S.mode={chat:'Chat',plan:'Plan',act:'Act',goal:'Goal'}[command[1].toLowerCase()];S.draft=d.slice(command[0].length).trim();if(!S.draft){render();toast('会话模式已更新，没有发送命令文本');return}}if(S.model.startsWith('Helix')&&S.account!=='member'){modalReturn='models';open('login');return}S.messages.push({role:'user',text:S.draft||'请查看选中的材料。'},{role:'assistant',text:'正在整理你提供的内容…'});S.draft='';S.attachments=[];S.references=[];S.stream=true;S.tool='idle';renderChat();later(()=>{if(!S.stream)return;S.messages[S.messages.length-1].text='方案分为三步：先核对来源与权限，再整理可执行步骤，最后由你确认需要修改的部分。\n\n识别文字实时进入输入框；结束录音后在原处编辑，只有主动点击发送才提交。取消录音恢复原来的文字。';S.stream=false;renderChat()},2200)}
