function freshChat(){const d=intentState();S.permission=d.permissionDefault;S.expert='默认助手';S.connector=false;S.skill=false;delete d.memberships.current;S.saved.previousMessages=structuredClone(S.messages);S.saved.previousDraft=S.draft;S.stream=false;S.messages=[];S.draft='';S.attachments=[];S.references=[];S.mode='Act';S.recordTitle='新会话';go('chat')}
function seedMessages(){S.recordTitle='云端语音接入方案';S.messages=[{role:'user',text:'请整理语音输入的权限与取消流程。'},{role:'assistant',text:'先让用户明确开始录音，再展示实时识别预览。结束后允许编辑，用户确认才加入草稿。取消保留原有文字。'}];S.tool='等待授权'}
function performConfirm(a){close(false);if(a==='new'){freshChat();return}if(a.startsWith('branch-')){S.saved.previousMessages=structuredClone(S.messages);S.messages=S.messages.slice(0,Number(a.slice(7))+1);S.branch++;toast('新分支已创建，原分支保留')}else switch(a){case 'preview-reset':go('setup');return;case 'camera':S.attachments.push('拍摄照片.jpg · 演示');break;case 'full-access':S.permission='完全访问';break;case 'logout':S.account='guest';break;case 'goal-resume':S.goal='正在推进 · 新 Run';break;case 'goal-cancel':S.goal='已取消 · 原效果保留';break;case 'disconnect':S.connected=false;S.connector=false;break;case 'local-import':S.saved.localImported=true;toast('演示资产已导入，未自动加载');break;case 'share':toast('模拟分享完成，未调用系统分享');break;case 'question':S.knowledgeSaved=true;break;case 'schedule-stop':toast('原 attempt 已收到停止请求；未来规则未改变');break;case 'file-reload':S.saved.fileRecovery=S.fileText;S.fileText='# 远端新版本\n内容已更新。';S.fileConflict=false;break;case 'restore-copy':toast('已模拟恢复到独立副本，原文件保留');break;case 'directory':toast('模拟授权目录已选择；在途调用目录未改变');break;case 'install':S.installed=true;break;case 'uninstall':S.installed=false;S.pluginEnabled=false;break;case 'skill-import':go('skill');return;case 'cloud-asr':toast('云端上传范围已模拟确认');break;case 'cache':toast('模拟缓存已清理，用户内容保留');break;case 'archive':S.saved.archived=true;go('history');S.filter='archived';break;case 'delete-conversation':S.saved.conversationDeleted=true;S.saved.previousMessages=structuredClone(S.messages);S.messages=[];S.recordTitle='新会话';go('history');break;case 'delete-artifact':S.saved.artifactDeleted=true;go('artifacts');break;case 'delete-reminder':S.saved.reminderDeleted=true;go('reminders');break;case 'delete-file':S.saved.fileDeleted=true;go('files');break;}render()}
function showExtra(a){const extra={
'language':['应用语言',`<label>语言<select id="generic-value"><option>简体中文</option><option>English</option></select></label>`],
'lan':['LAN 范围',field('允许网段（示例）','generic-value','192.168.1.0/24')+note('用户授权网段不等于将所有服务标为本机。')],
'egress':['出站与数据规则',field('允许目标（示例）','generic-value','https://api.example.invalid')+note('数据内容与目的地分别校验；来源输出不能授予授权。')],
'quickjs':['QuickJS 原生访问',check('允许原生访问（私有进程 / 共享 UID）','quickjs-native')+note('默认 isolated UID；共享 UID 不声称凭据隔离。')],
'environment':['环境变量',field('演示变量','generic-value','LANG=zh_CN.UTF-8')],
'cloud-speech':['云端语音配置',field('ASR / TTS 服务地址（演示）','generic-value','https://speech.example.invalid')+note('语音独立接入；显式展示音频或正文上传范围。')],
'system-voice':['系统语音',field('系统音色（演示）','generic-value','默认中文')+note('原型不打开系统设置或播放声音。')],
};if(extra[a]){open('form',{title:extra[a][0],body:extra[a][1],saveKey:a});return}
const messages={'git-diff':['差异预览','<pre>+ 用户确认后加入草稿\n- 识别后自动发送</pre><p>仅为设计示例，不修改源码。</p>'],'runtime-log':['Runtime 日志','<pre>runtime: private process\nauth: not queried\nsecrets: redacted</pre>'],'diagnostic-report':['诊断报告预览','<p>版本：原型 1；数据：模拟。调用身份 call-demo-003，结果与模型消费分别记录。</p><p>报告无真实设备、账号、日志或密钥。</p>'],'notification-permission':['通知权限（模拟）','<p>原型不申请 Android 权限。拒绝后提醒列表仍可用，通知不可达需明确告知。</p>'+btn('模拟拒绝','permission-notice-deny','outline')+btn('模拟允许','permission-notice-allow','primary')],'automation-check':['自动化条件','<p>Advanced · Shizuku 未连接 / 无障碍未授权（模拟）。普通会话仍可用。</p>'],'screen-consent':['屏幕使用授权','<p>只作用于本次明确屏幕使用范围，不是所有工具的永久授权。</p>'],'licenses':['许可与归属','<p>本原型图标由本任务手写 SVG，使用系统字体，无远程资源。实际产品许可应保留原仓库资产清单及归属。</p>'],'permission-notice-deny':['通知被拒绝','提醒已保留，无法承诺系统通知送达。'],'permission-notice-allow':['模拟授权完成','未申请真实系统权限。']};if(messages[a])info(...messages[a]);else toast('未识别的演示操作：'+a)}
function scenario(id){clearTimers();S=initial();stack=[];modal=null;modalReturn=null;S.state='ready';S.formError='';if(detailScenario(id)){drawer(false);$('#catalog').hidden=true;return}switch(id){case 'blank':freshChat();break;case 'login-return':S.account='guest';S.draft='这段草稿登录后应保留';S.modelQuery='Helix';S.modelCandidate='Helix 内置 · 演示模型';go('chat');open('models');break;case 'expired':S.account='expired';S.draft='账号过期时保留的草稿';go('account');break;case 'stream':seedMessages();S.stream=true;go('chat');break;case 'voice':S.draft='原来的文字';S.voicePermission=true;go('chat');inlineVoiceStart();break;case 'approval':seedMessages();S.tool='等待授权';go('chat');open('tool');break;case 'unknown':seedMessages();S.tool='副作用未知 · UNKNOWN';S.goal='阻塞 · 副作用未知';go('goal');open('tool');break;case 'blocked':S.goal='阻塞 · 自动轮数耗尽';go('goal');break;case 'permission':go('chat');S.voice='idle';detailsState().voiceError='麦克风权限被拒绝；仍可文字输入。';render();break;case 'error':go('models');S.state='error';render();break;case 'empty':go('history');S.query.history='不存在的结果';render();break;case 'loading':go('knowledge');S.state='loading';render();break;case 'conflict':detailsState();go('file');S.fileConflict=true;render();break;case 'first':go('setup');break}drawer(false);$('#catalog').hidden=true}
function renderCatalog(){$('#catalog').innerHTML=`<div class="row between"><strong>评审控制台 · 不属于产品界面</strong><small>页面 ${PAGES.length} · 专项场景 ${SCENARIOS.length} · 所有状态可复位</small></div><div class="review-state"><label>构建渠道<select id="review-build"><option value="Standard">Standard</option><option value="Advanced">Advanced</option></select></label><label>问题样例<select id="question-choice-mode"><option value="multiple">多选</option><option value="single">单选</option></select></label><label>当前页状态<select id="state-control"><option value="ready">正常</option><option value="loading">加载中</option><option value="empty">空</option><option value="error">错误</option></select></label><label>账号<select id="account-control"><option value="guest">未登录</option><option value="member">已登录</option><option value="expired">已过期</option></select></label></div><div class="catalog-grid">${SCENARIOS.map(([id,t])=>btn(t,'scenario:'+id,'outline')).join('')}${PAGES.map(p=>`<button data-route="${p.id}">${icon('file')}<span><small>${p.group}</small>${p.title}</span></button>`).join('')}</div>`}
document.addEventListener('click',e=>{const r=e.target.closest('[data-route]');if(r){go(r.dataset.route);return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a.startsWith('scenario:'))scenario(a.slice(9));else handle(a)});
document.addEventListener('input',e=>{const t=e.target;detailInput(t);if(t.id==='draft')S.draft=t.value;if(t.id==='voice-text')S.voiceText=t.value;if(t.id==='file-body')S.fileText=t.value;if(t.id==='note-body')S.noteText=t.value;if(t.id==='model-search'){S.modelQuery=t.value;$('#model-options').innerHTML=modelOptions()}if(t.dataset.search){const key=t.dataset.search;S.query[key]=t.value;const start=t.selectionStart;if(modal)renderModal();else render();const fresh=document.querySelector(`[data-search="${key}"]`);fresh?.focus();fresh?.setSelectionRange(start,start)}});
document.addEventListener('change',e=>{const t=e.target;if(detailChange(t))return;if(t.dataset.check){const k=t.dataset.check;if(k==='session-skill')S.skill=t.checked;else if(k==='session-connector'){if(t.checked&&!S.connected){t.checked=false;toast('请先连接资料服务');return}S.connector=t.checked}else if(k==='plugin-enabled')S.pluginEnabled=t.checked;else{S.selected=S.selected.filter(x=>x!==k);if(t.checked)S.selected.push(k)}}if(t.id==='state-control'){S.state=t.value;render()}if(t.id==='account-control'){S.account=t.value;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal){e.preventDefault();if(['login','register','auth-loading'].includes(modal.type))handle('auth-cancel');else handle('close')}else drawer(false)}if(e.target.id==='draft'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();send()}if(modal&&e.key==='Tab'){const f=[...$('#overlay').querySelectorAll('button,input,textarea,select,a')].filter(x=>!x.disabled&&!x.hidden);if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('visibilitychange',()=>{if(document.hidden){S.tts=false;if(S.voice==='recording'){inlineVoiceCancel('录音因切到后台停止，原草稿保留');render()} }});
$('#drawer-mask').addEventListener('click',()=>drawer(false));$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay'){if(['login','register','auth-loading'].includes(modal?.type))handle('auth-cancel');else handle('close')}});
$('#theme').addEventListener('change',e=>{$('#app').dataset.theme=e.target.value});$('#viewport').addEventListener('change',e=>{$('#app').classList.toggle('phone',e.target.value==='phone');drawer(false);intentWorkbench()});$('#catalog-toggle').addEventListener('click',()=>{$('#catalog').hidden=!$('#catalog').hidden});$('#reset').addEventListener('click',reset);
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1)||'chat';if(id!==route)go(id)});
S=initial();const firstRoute=location.hash.slice(1);if(PAGES.some(p=>p.id===firstRoute))route=firstRoute;renderCatalog();render();
/* 窄接口仅供离线 DOM 测试，不存储凭据、不访问网络。 */
window.HelixPrototype={pages:PAGES,scenarios:SCENARIOS,go,handle,scenario,reset,getState:()=>structuredClone(S),getRoute:()=>route,getModal:()=>modal?.type};
